-- Old WordPress blog imported 2026-11-02 13:33
SET NAMES utf8mb4;



-- Links between articles use the old WordPress addresses (www.sunsys.in/<slug>); fixes copies imported earlier
UPDATE posts SET blocks = REPLACE(blocks, 'https://sunsys.in/blog/post/?slug=', 'https://www.sunsys.in/') WHERE blocks LIKE '%https://sunsys.in/blog/post/?slug=%';
